Criar um jogo 3D completo com gráficos de qualidade profissional (como GTA ou Skyrim), um mapa gigante e sistemas de tribo, requer meses de trabalho de equipes inteiras, engines pesadas (Unity/Unreal) e terabytes de dados. Como sou uma Inteligência Artificial baseada em texto, **eu não posso gerar um arquivo de aplicativo (APK ou IPA) pronto para baixar**, pois isso exige compilação complexa e servidores dedicados.

No entanto, eu posso fazer algo incrível para você agora mesmo: **posso escrever o código completo de um Protótipo Funcional 3D usando tecnologias da Web (Three.js)**.

Este código vai criar um mini-jogo 3D onde você pode voar/andar, ver árvores, nuvens, interagir com opções de tribos e usar controles de toque na tela do celular. Para rodar no celular sem instalar nada pesado, faremos ele funcionar como uma **Aplicação Web**.

Aqui está o seu jogo 3D pronto e o passo a passo para rodá-lo no seu dispositivo.

### O Código do Jogo (HTML + JavaScript 3D)

Copie todo o código abaixo e salve em um arquivo chamado `jogo.html` no seu computador.

```html
<!DOCTYPE html>
<html lang="pt-br">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, user-scalable=no">
    <title>Mini RPG Tribal 3D</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #87CEEB; font-family: sans-serif; touch-action: none; }
        canvas { display: block; }

        /* Interface do Usuário */
        #ui-layer { position: absolute; top: 0; left: 0; width: 100%; height: 100%; pointer-events: none; }

        /* Controles Mobile */
        #controls { position: absolute; bottom: 20px; left: 20px; pointer-events: auto; display: flex; gap: 15px;}
        .btn { 
            width: 60px; height: 60px; background: rgba(255,255,255,0.5); border-radius: 50%; border: 2px solid white; 
            font-size: 24px; display: flex; align-items: center; justify-content: center; color: black;
            user-select: none;
        }

        /* Seleção de Tribo */
        #tribe-menu { 
            position: absolute; top: 20px; right: 20px; display: flex; flex-direction: column; gap: 10px; pointer-events: auto;
        }
        .tribe-btn {
            padding: 10px 20px; border: 2px solid white; border-radius: 10px; cursor: pointer; background: rgba(0,0,0,0.5);
        }
        .tribe-btn.selected { background: gold; color: black; font-weight: bold; }

        /* Mensagem de Status */
        #status-text {
            position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%);
            color: white; font-size: 2rem; text-shadow: 2px 2px 4px black; display: none;
        }

        /* Instruções */
        #instructions {
            position: absolute; top: 5px; width: 100%; text-align: center; color: rgba(255,255,255,0.7); font-size: 12px;
        }
    </style>
</head>
<body>

    <div id="instructions">Use os botões abaixo para se mover</div>

    <div id="ui-layer">
        <!-- Menu de Tribos -->
        <div id="tribe-menu">
            <div class="tribe-btn selected" onclick="joinTribe('Sombra', '#5c3b1d')">🔴 Tribo Sombra</div>
            <div class="tribe-btn" onclick="joinTribe('Foguinho', '#ffcc00')">🟡 Tribo Fogo</div>
            <div class="tribe-btn" onclick="joinTribe('Água', '#0088ff')">🔵 Tribo Água</div>
        </div>

        <!-- Botões de Movimento -->
        <div id="controls">
            <div class="btn" ontouchstart="movePlayer(true)" ontouchend="movePlayer(false)" onmousedown="movePlayer(true)" onmouseup="movePlayer(false)">⬆️</div>
            <div class="btn" ontouchstart="movePlayer(false)" ontouchend="movePlayer(false)" onmousedown="movePlayer(false)" onmouseup="movePlayer(false)">⬇️</div>
            <div class="btn" ontouchstart="movePlayer(false)" ontouchend="movePlayer(false)" onmousedown="movePlayer(false)" onmouseup="movePlayer(false)">⬅️</div>
            <div class="btn" ontouchstart="movePlayer(false)" ontouchend="movePlayer(false)" onmousedown="movePlayer(false)" onmouseup="movePlayer(false)">➡️</div>
        </div>

        <div id="status-text"></div>
    </div>

    <!-- Importando Three.js via CDN -->
    <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>

    <script>
        // --- Configuração Inicial da Cena 3D ---
        const scene = new THREE.Scene();
        scene.background = new THREE.Color(0x87CEEB); // Céu azul
        scene.fog = new THREE.Fog(0x87CEEB, 10, 150); // Névoa para profundidade

        const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);

        const renderer = new THREE.WebGLRenderer({ antialias: true });
        renderer.setSize(window.innerWidth, window.innerHeight);
        document.body.appendChild(renderer.domElement);

        // --- Lógica do Mapa e Objetos ---

        // Chão
        const geometryGround = new THREE.PlaneGeometry(200, 200);
        const materialGround = new THREE.MeshLambertMaterial({ color: 0x3b7d3b }); // Verde floresta
        const ground = new THREE.Mesh(geometryGround, materialGround);
        ground.rotation.x = -Math.PI / 2;
        ground.position.y = -5; // Elevação levemente
        scene.add(ground);

        // Função para criar árvores
        function createTree(x, z) {
            const trunkGeo = new THREE.CylinderGeometry(0.5, 0.5, 3, 8);
            const trunkMat = new THREE.MeshLambertMaterial({ color: 0x8B4513 });
            const trunk = new THREE.Mesh(trunkGeo, trunkMat);

            const leavesGeo = new THREE.DodecahedronGeometry(2);
            const leavesMat = new THREE.MeshLambertMaterial({ color: 0x228B22 });
            const leaves = new THREE.Mesh(leavesGeo, leavesMat);
            leaves.position.y = 2; // No topo da árvore

            const tree = new THREE.Group();
            tree.add(trunk);
            tree.add(leaves);
            tree.position.set(x, 0, z);
            scene.add(tree);
        }

        // Gerar terreno procedural simples
        for (let i = 0; i < 150; i++) {
            createTree((Math.random() - 0.5) * 100, (Math.random() - 0.5) * 100);
        }

        // Nuvens
        const cloudGeo = new THREE.BoxGeometry(10, 4, 10);
        const cloudMat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.8 });

        for(let j=0; j<10; j++) {
            const cloud = new THREE.Mesh(cloudGeo, cloudMat);
            cloud.position.set((Math.random()-0.5)*100, 30 + Math.random()*20, (Math.random()-0.5)*100);
            scene.add(cloud);
        }

        // --- Jogador ---
        const playerGeo = new THREE.SphereGeometry(1, 32, 32);
        const playerMat = new THREE.MeshPhongMaterial({ color: 0xff0000 }); // Cor muda conforme tribo
        const player = new THREE.Mesh(playerGeo, playerMat);
        scene.add(player);

        camera.position.set(0, 5, 10);
        camera.lookAt(player.position);

        // Câmera segue o jogador suavemente
        function updateCamera() {
            const speed = 0.5;
            const distance = 5;
            const angle = Math.atan2(player.position.y - camera.position.y, player.position.z - camera.position.z);

            camera.position.x += (player.position.x - camera.position.x) * 0.1;
            camera.position.z += (player.position.z - camera.position.z) * 0.1;
            camera.lookAt(player.position.x, player.position.y, player.position.z);
        }

        // --- Variáveis do Controle ---
        let keys = { w: false, a: false, s: false, d: false };
        let isMoving = false;

        // Input de Teclado
        document.addEventListener('keydown', (e) => {
            switch(e.key.toLowerCase()) {
                case 'w': keys.w = true; break;
                case 'a': keys.a = true; break;
                case 's': keys.s = true; break;
                case 'd': keys.d = true; break;
            }
        });
        document.addEventListener('keyup', (e) => {
            switch(e.key.toLowerCase()) {
                case 'w': keys.w = false; break;
                case 'a': keys.a = false; break;
                case 's': keys.s = false; break;
                case 'd': keys.d = false; break;
            }
        });

        // Input de Toque (Touch Events)
        function movePlayer(dir) {
            isMoving = dir;
            document.getElementById('status-text').innerText = "Andando...";
        }

        // Sistema de Tribos
        let currentTribeColor = 0xff0000;
        let selectedTribeName = "";

        window.joinTribe = function(name, colorHex) {
            selectedTribeName = name;
            // Atualiza visualmente os botões
            const btns = document.querySelectorAll('.tribe-btn');
            btns.forEach(btn => {
                btn.classList.remove('selected');
                if(btn.innerText.includes(name)) btn.classList.add('selected');
            });

            // Muda cor do jogador
            player.material.color.setHex(colorHex);
            alert(`Você juntou-se à ${name}! Sua cor mudou.`);

            document.getElementById('status-text').innerText = `${name}: ${name}`;
        }

        // --- Loop do Jogo (Renderização) ---
        function animate() {
            requestAnimationFrame(animate);

            // Movimentação simples baseada nos botões
            if (isMoving) {
                if(keys.w || (typeof navigator !== 'undefined' && navigator.vibrate)) {
                    player.position.x -= 0.2;
                    player.position.z -= 0.2; // Frente
                }
                if(keys.s) {
                    player.position.x += 0.2;
                    player.position.z += 0.2; // Trás
                }
                if(keys.a) {
                    player.position.x += 0.2;
                    player.position.z += 0.2; // Direita (para frente no joystick lateral)
                }
            }

            updateCamera();
            renderer.render(scene, camera);
        }

        // Redimensionar janela
        window.addEventListener('resize', () => {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        });

        animate();
    </script>
</body>
</html>
```

