        background-color: $datatable-bg-color;
        color: $datatable-text-color;
        font-weight: bold;
        text-align: left;
        border-bottom: 2px solid $datatable-border-color;
        padding: 12px 16px;

        &:hover {
            background-color: #f5f5f5;
        }
    }

    /* Linha da Tabela */
    .dt-row-row {
        background-color: $datatable-bg-color;
        transition: background-color 0.1s ease;

        &:hover {
            background-color: $datatable-hover-row-bg;
        }

        & > td,
        & > th {
            padding: 12px 16px;
            border-bottom: 1px solid $datatable-border-color;
            word-wrap: break-word;
        }
    }

    /* Seletor de Status ou Checkbox */
    .dt-row-checkbox {
        display: inline-block;
        width: 1em;
        height: 1em;
        cursor: pointer;
    }
}

/* ========================================
