//+------------------------------------------------------------------+
//| Função para calcular a Média Móvel                             |
//+------------------------------------------------------------------+
void SimpleMAOnBuffer(int rates_total, int prev_calculated, const double &price[], double &buffer[])
  {
   int start = MathMax(prev_calculated - 1, SMA_Period);  // Começa onde começa a média
   for (int i = start; i < rates_total; i++) 
     {
      double sum = 0.0;
      for (int j = 0; j < SMA_Period; j++) 
         sum += price[i - j];
      buffer[i] = sum / SMA_Period;  // Calcula a média simples
     }
  }

