//| Verifica condições para alertar                                |
//+------------------------------------------------------------------+
void CheckAlerts(int rates_total, const double &price[])
  {
   // Obtém o preço atual e a média no último candle
   double currentPrice = price[rates_total - 1];
   double smaValue = SMABuffer[rates_total - 1];

   // Calcula a distância entre o preço e a média
   double distance = MathAbs(currentPrice - smaValue);

   // Converte ponto do mercado em valor real
   double minPoint = SymbolInfoInteger(_Symbol, SYMBOL_TRADE_STATUS);
   minPoint = _Digits;

   // Verifica se estamos dentro do intervalo de sensibilidade definido
   if (distance <= Sensibilidade * _Point && PreviousAlertPrice != currentPrice)
     {
      // Envia mensagem de alerta visual
      string mensagem = "O preço tocou ou chegou perto da SMA! Preço: " + DoubleToString(currentPrice, _Digits);
      Alert(mensagem);

      // Envia notificação para o celular (se ativado)
      if (Notificacao_Ativa)
         SendNotification(mensagem);

      // Atualiza o último preço alertado
      PreviousAlertPrice = currentPrice;
     }
  }
